"use client";

import {
  useEffect,
  useId,
  useRef,
  useState,
  type ComponentProps,
  type FormEvent,
  type KeyboardEvent,
} from "react";
import {
  ArrowUpIcon,
  ChevronDownIcon,
  FileTextIcon,
  ImageIcon,
  PlusIcon,
  SquareIcon,
} from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  Menu,
  MenuContent,
  MenuItem,
  MenuRadioGroup,
  MenuRadioItem,
  MenuTrigger,
} from "@/components/ui/menu";
import { cn } from "@/lib/utils";

export interface PromptComposerSubmitEvent {
  prompt: string;
}

export interface PromptComposerAttachmentOption {
  id: string;
  label: string;
  description?: string;
  kind?: "file" | "image" | "folder";
}

export interface PromptComposerProps {
  /** Controlled draft text. */
  value?: string;
  /** Initial draft text when the component is uncontrolled. */
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onSubmit?: (event: PromptComposerSubmitEvent) => void;
  /** Called while a response is being generated. */
  onStop?: () => void;
  /** Replaces Send with Stop and prevents edits until the response ends. */
  isRunning?: boolean;
  disabled?: boolean;
  placeholder?: string;
  /** Limits the number of characters in the draft. */
  maxLength?: number;
  /** Optional model choices, rendered as a compact footer menu. */
  models?: readonly string[];
  model?: string;
  onModelChange?: (model: string) => void;
  /** Choices opened by the attachment menu above the composer. */
  attachmentOptions?: readonly PromptComposerAttachmentOption[];
  onAttachmentOptionSelect?: (option: PromptComposerAttachmentOption) => void;
  className?: string;
}

/**
 * The minimal prompt surface shared by chat, generation, and agent products.
 * Attachments and model choice are optional, controlled enhancements.
 */
function PromptComposer({
  value,
  defaultValue = "",
  onValueChange,
  onSubmit,
  onStop,
  isRunning = false,
  disabled = false,
  placeholder = "Message…",
  maxLength,
  models = [],
  model,
  onModelChange,
  attachmentOptions = [],
  onAttachmentOptionSelect,
  className,
}: PromptComposerProps) {
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue);
  const textareaId = useId();
  const statusId = useId();
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const prompt = value ?? uncontrolledValue;
  const canSubmit = prompt.trim().length > 0 && !disabled && !isRunning;

  useEffect(() => {
    const textarea = textareaRef.current;
    if (!textarea) return;
    textarea.style.height = "0px";
    textarea.style.height = `${Math.min(textarea.scrollHeight, 160)}px`;
  }, [prompt]);

  function setPrompt(nextValue: string) {
    if (value === undefined) setUncontrolledValue(nextValue);
    onValueChange?.(nextValue);
  }

  function submit() {
    if (!canSubmit) return;
    onSubmit?.({ prompt: prompt.trim() });
  }

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    submit();
  }

  function handleKeyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
    if (event.nativeEvent.isComposing || event.key !== "Enter" || event.shiftKey) return;
    event.preventDefault();
    submit();
  }

  return (
    <form
      data-slot="prompt-composer"
      className={cn(
        "w-full rounded-[20px] border border-border bg-card p-2 shadow-[0_18px_40px_-32px_color-mix(in_oklab,var(--foreground)_70%,transparent)] transition-[border-color,box-shadow] duration-quick focus-within:border-ring/70 focus-within:ring-1 focus-within:ring-ring/25 dark:bg-card/80",
        className,
      )}
      onSubmit={handleSubmit}
    >
      <span id={statusId} role="status" aria-live="polite" className="sr-only">
        {isRunning ? "Generating response. Stop is available." : "Ready to send prompt."}
      </span>

      <label htmlFor={textareaId} className="sr-only">
        Prompt
      </label>
      <textarea
        ref={textareaRef}
        id={textareaId}
        value={prompt}
        disabled={disabled || isRunning}
        aria-describedby={statusId}
        placeholder={placeholder}
        maxLength={maxLength}
        rows={1}
        className="block max-h-40 min-h-14 w-full resize-none overflow-y-auto bg-transparent px-2.5 py-3 text-body leading-6 text-foreground outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-60"
        onChange={(event) => setPrompt(event.target.value)}
        onKeyDown={handleKeyDown}
      />

      <div className="flex min-h-9 items-center gap-1 border-t border-border/60 px-0.5 pt-2">
        {attachmentOptions.length > 0 ? (
          <Menu>
            <MenuTrigger
              render={
                <Button
                  type="button"
                  variant="ghost"
                  size="icon-sm"
                  disabled={disabled || isRunning}
                  aria-label="Add an attachment"
                  title="Add an attachment"
                  className="rounded-full text-muted-foreground hover:text-foreground"
                />
              }
            >
              <PlusIcon />
            </MenuTrigger>
            <MenuContent align="start" side="top" sideOffset={8} className="w-60">
              {attachmentOptions.map((option) => (
                <MenuItem key={option.id} onClick={() => onAttachmentOptionSelect?.(option)}>
                  {option.kind === "image" ? <ImageIcon /> : <FileTextIcon />}
                  <span className="flex min-w-0 flex-col">
                    <span>{option.label}</span>
                    {option.description ? (
                      <span className="text-minor leading-4 text-muted-foreground">
                        {option.description}
                      </span>
                    ) : null}
                  </span>
                </MenuItem>
              ))}
            </MenuContent>
          </Menu>
        ) : null}
        {models.length > 0 ? (
          <Menu>
            <MenuTrigger
              render={
                <Button type="button" variant="ghost" size="sm" disabled={disabled || isRunning} />
              }
            >
              <ModelProviderIcon model={model ?? models[0]} />
              <span className="max-w-28 truncate">{model ?? models[0]}</span>
              <ChevronDownIcon className="size-3 opacity-50" />
            </MenuTrigger>
            <MenuContent align="start" side="top" sideOffset={8} className="w-52">
              <MenuRadioGroup value={model ?? models[0]} onValueChange={onModelChange}>
                {models.map((option) => (
                  <MenuRadioItem
                    key={option}
                    value={option}
                    indicator="check"
                    className="data-checked:bg-active data-checked:text-foreground"
                  >
                    <ModelProviderIcon model={option} />
                    {option}
                  </MenuRadioItem>
                ))}
              </MenuRadioGroup>
            </MenuContent>
          </Menu>
        ) : null}
        <span className="flex-1" />
        {isRunning ? (
          <Button
            type="button"
            size="icon-sm"
            variant="destructive"
            onClick={onStop}
            disabled={disabled}
            aria-label="Stop generating"
            title="Stop generating"
            className="rounded-full"
          >
            <SquareIcon className="fill-current" />
          </Button>
        ) : (
          <Button
            type="submit"
            size="icon-sm"
            disabled={!canSubmit}
            aria-label="Send prompt"
            title="Send prompt (Enter)"
            className="rounded-full"
          >
            <ArrowUpIcon />
          </Button>
        )}
      </div>
    </form>
  );
}

function ModelProviderIcon({ model }: { model: string }) {
  return model.toLocaleLowerCase().includes("claude") ? <AnthropicIcon /> : <OpenAIIcon />;
}

function OpenAIIcon(props: ComponentProps<"svg">) {
  return (
    <svg viewBox="0 0 260 260" fill="none" aria-hidden {...props} className="size-3.5 shrink-0">
      <path
        fill="currentColor"
        d="M239.184 106.203a64.72 64.72 0 0 0-5.576-53.103C219.452 28.459 191 15.784 163.213 21.74A65.586 65.586 0 0 0 52.096 45.22a64.72 64.72 0 0 0-43.23 31.36c-14.31 24.602-11.061 55.634 8.033 76.74a64.67 64.67 0 0 0 5.525 53.102c14.174 24.65 42.644 37.324 70.446 31.36a64.72 64.72 0 0 0 48.754 21.744c28.481.025 53.714-18.361 62.414-45.481a64.77 64.77 0 0 0 43.229-31.36c14.137-24.558 10.875-55.423-8.083-76.483m-97.56 136.338a48.4 48.4 0 0 1-31.105-11.255l1.535-.87l51.67-29.825a8.6 8.6 0 0 0 4.247-7.367v-72.85l21.845 12.636c.218.111.37.32.409.563v60.367c-.056 26.818-21.783 48.545-48.601 48.601M37.158 197.93a48.35 48.35 0 0 1-5.781-32.589l1.534.921l51.722 29.826a8.34 8.34 0 0 0 8.441 0l63.181-36.425v25.221a.87.87 0 0 1-.358.665l-52.335 30.184c-23.257 13.398-52.97 5.431-66.404-17.803M23.549 85.38a48.5 48.5 0 0 1 25.58-21.333v61.39a8.29 8.29 0 0 0 4.195 7.316l62.874 36.272l-21.845 12.636a.82.82 0 0 1-.767 0L41.353 151.53c-23.211-13.454-31.171-43.144-17.804-66.405zm179.466 41.695l-63.08-36.63L161.73 77.86a.82.82 0 0 1 .768 0l52.233 30.184a48.6 48.6 0 0 1-7.316 87.635v-61.391a8.54 8.54 0 0 0-4.4-7.213m21.742-32.69l-1.535-.922l-51.619-30.081a8.39 8.39 0 0 0-8.492 0L99.98 99.808V74.587a.72.72 0 0 1 .307-.665l52.233-30.133a48.652 48.652 0 0 1 72.236 50.391zM88.061 139.097l-21.845-12.585a.87.87 0 0 1-.41-.614V65.685a48.652 48.652 0 0 1 79.757-37.346l-1.535.87l-51.67 29.825a8.6 8.6 0 0 0-4.246 7.367zm11.868-25.58L128.067 97.3l28.188 16.218v32.434l-28.086 16.218l-28.188-16.218z"
      />
    </svg>
  );
}

function AnthropicIcon(props: ComponentProps<"svg">) {
  return (
    <svg viewBox="0 0 256 176" fill="none" aria-hidden {...props} className="size-3.5 shrink-0">
      <path
        fill="currentColor"
        d="m147.487 0l70.081 175.78H256L185.919 0zM66.183 106.221l23.98-61.774l23.98 61.774zM70.07 0L0 175.78h39.18l14.33-36.914h73.308l14.328 36.914h39.179L110.255 0z"
      />
    </svg>
  );
}

export { PromptComposer };
